import{_ as t,a as o,b as a}from"./chunks/f9821b408306879ff46d.CdO9ZVdu.js";import{_ as r,o as n,c as i,a6 as s}from"./chunks/framework.CnPv4DE1.js";const f=JSON.parse('{"title":"How To Write Authentic Content (Social Media Growth 101)","description":"","frontmatter":{"title":"How To Write Authentic Content (Social Media Growth 101)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/dont-get-replaced-by-ai-how-to-write-authentic-content.md","filePath":"en/letters/dont-get-replaced-by-ai-how-to-write-authentic-content.md"}'),p={name:"en/letters/dont-get-replaced-by-ai-how-to-write-authentic-content.md"};function h(l,e,u,c,d,m){return n(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="how-to-write-authentic-content-social-media-growth-101" tabindex="-1">How To Write Authentic Content (Social Media Growth 101) <a class="header-anchor" href="#how-to-write-authentic-content-social-media-growth-101" aria-label="Permalink to &quot;How To Write Authentic Content (Social Media Growth 101)&quot;">​</a></h1><p>Dan Koe · 2023-01-20 · <a href="https://thedankoe.com/letters/dont-get-replaced-by-ai-how-to-write-authentic-content/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/dont-get-replaced-by-ai-how-to-write-authentic-content">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/wwtt8lkMRDQ?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><em>People want to follow humans.</em></p><p>They don’t want to follow a search engine with a face on it.</p><p>And, with the rise of ChatGPT and future iterations of language AI, authenticity is more important than ever.</p><p>Everyone is desperate for human connection, and social media is not delivering that.</p><p>You can, and it will lead to more authority than you could imagine.</p><p>Authenticity, from my predictions, will be the differentiating factor for the future generation of creators (which is why I talk about philosophy, self-awareness, and other non-business topics that actually make you stand out in business).</p><p>I’ve worked directly and indirectly with over 5,000 creators, and this is a problem they encounter time and time again.</p><p><em>This seems to be the most overwhelming problem.</em></p><p>Creators don’t know how to incorporate who they are into their content.</p><p>This makes people quit before it starts getting good.</p><p>And, even if you stick it out, if you don’t display who you are and where you came from, what separates you from a robot?</p><p>Even worse, people that try to incorporate more than one interest don’t know how to write in a way that leads to growth, authority, and engagement.</p><p>Before we dive into organizing your topics, writing content, and turning 1 idea into 10, here’s a bit of credibility:</p><p>I started as a creator 3 years ago.</p><p>I launched a product right when I started, which most people warn against.</p><p>I wrote about anything I wanted to, like emotional management and self-improvement, when my product was related to web design.</p><p>I incorporated web design tweets here and there (maybe once every 2 days?) because I knew it was important.</p><p>The most important thing for those worried about monetization:</p><p>Talk about whatever you want, and when you plan to promote, talk about that topic more.</p><p>It’s that simple.</p><p>Well, kinda.</p><p>Experience will teach you more than I can here.</p><p><strong>Before we dive in:</strong></p><p>The first Solopreneur Sprint starts February 7th.</p><p>In 14 days, we will create confidence in your niche of one, create 20+ foundational content pieces, and create a zero-cost growth strategy for your creator brand.</p><p><a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">&gt;&gt; Check it out here if interested.</a></p><h2 id="your-topic-tree" tabindex="-1">Your Topic Tree <a class="header-anchor" href="#your-topic-tree" aria-label="Permalink to &quot;Your Topic Tree&quot;">​</a></h2><p>If you don’t know what to write about, <a href="https://thedankoe.com/the-most-profitable-niche-is-you-how-to-create-your-niche/" target="_blank" rel="noreferrer">read the last letter about turning yourself into the niche.</a></p><p>In that letter, we outlined your life story and turned it into book chapters.</p><p>What skills and interests are going to help you create your ideal future?</p><p>And for those that are already on the path, what skills, interests, and expertise do you have that have helped you achieve your goals?</p><p>Understand that non-money-making interests help you achieve your goals as well.</p><p>If your ideal future consists of being at peace and not worrying about money…</p><p>It sounds like spirituality is the solution to all of those, not money. So, don’t hesitate to include the things you love talking about.</p><p>An added benefit is your passion for that interest will display in your content.</p><p>These are what we are going to use for our content.</p><h3 id="choose-2-3-interests-or-skills-you-want-to-write-about" tabindex="-1">Choose 2-3 Interests Or Skills You Want To Write About <a class="header-anchor" href="#choose-2-3-interests-or-skills-you-want-to-write-about" aria-label="Permalink to &quot;Choose 2-3 Interests Or Skills You Want To Write About&quot;">​</a></h3><p>These should already be at the top of your mind.</p><p>I can’t help you much here, as I am not you.</p><p>If you don’t have interests you want to write about, you need to set a goal, start pursuing it, and learn what will help you get there.</p><h3 id="broaden-breakdown" tabindex="-1">Broaden &amp; Breakdown <a class="header-anchor" href="#broaden-breakdown" aria-label="Permalink to &quot;Broaden &amp; Breakdown&quot;">​</a></h3><p>Most people start with hyper-specific interests like “biomechanical movement therapy” and get stressed out because so few people are interested in it.</p><p>Even further, they get stressed out again because they feel like if they don’t talk about that specific thing, their entire monetization potential goes down the drain.</p><p>Not how it works, my friend. Zoom out.</p><p>Let’s say my interests are:</p><ul><li>Web design</li><li>Weight lifting</li><li>Spirituality</li></ul><p>From those, I want to broaden them into the overarching market they reside in.</p><p>Web design = online business or business in general.</p><p>Weight lifting = bodybuilding or health in general.</p><p>Spirituality = self-actualization or improvement.</p><p>Now that we have 3 broad markets we can move within, we want to break them down into topics and sub-topics.</p><p>The beauty in this method:</p><p>If you want to make money with an interest like “biomechnical movement therapy,” you can attract people interested in health.</p><p>Then, you can slowly raise their awareness around bio movement and educate them on why its important.</p><p><em>You are not supposed to</em> <em>just</em> <em>attract people that know everything about your main interest</em>_._ Why would they buy from you?</p><p>With those 3 interests, grab a notebook and break them down like so:</p><p><img src="'+t+'" alt=""></p><p>Your job is to cover this entire domain in 6-12 months with all lengths of content.</p><p>That is how your brand perception is formed.</p><h3 id="remember-the-3-pillars-of-social-leverage" tabindex="-1">Remember The 3 Pillars Of Social Leverage <a class="header-anchor" href="#remember-the-3-pillars-of-social-leverage" aria-label="Permalink to &quot;Remember The 3 Pillars Of Social Leverage&quot;">​</a></h3><p>Before we start creating content, we want to have a balance of the content style we write.</p><p>The 3 pillars of social leverage are growth, authenticity, and authority.</p><p>Your content, on a 1-2 month timescale, should hit each of these.</p><p>If you aren’t growing, pivot.</p><p>If you aren’t making sales, pivot.</p><p>If you aren’t gaining loyal fans, pivot.</p><p>Iterate as you get more <em>real-world</em> feedback. You have to post, even if it sucks.</p><h2 id="how-to-write-3-authoritative-content-pieces" tabindex="-1">How To Write 3 Authoritative Content Pieces <a class="header-anchor" href="#how-to-write-3-authoritative-content-pieces" aria-label="Permalink to &quot;How To Write 3 Authoritative Content Pieces&quot;">​</a></h2><p>We are going to be writing tweets for this.</p><p>Why? Because tweets are the perfect length and structure for high-performing posts on any platform.</p><p>My LinkedIn posts, Instagram posts and reels, TikToks, and the rest are all based off of my tweets.</p><p>We are going to start by establishing authority in your main interest, the one that makes you money.</p><p>We will use “marketing” as an example.</p><p>With any of the examples below, you can:</p><ul><li>Turn them into threads or newsletters for more authority</li><li>Repurpose any point of the list into its own post</li><li>Copy and paste them to other platforms</li><li>Use them as scripts for Shorts, Reels, or TikToks</li></ul><p>Let’s dig in.</p><h3 id="actionable-principles" tabindex="-1">Actionable Principles <a class="header-anchor" href="#actionable-principles" aria-label="Permalink to &quot;Actionable Principles&quot;">​</a></h3><p>Simple, write a list that goes over actionable steps a beginner can take.</p><p>This helps you build authority in one interest. And, even advanced people will follow you, because they understand the importance of the fundamental principles.</p><p>For all of these, please keep in mind that you should follow a hook &gt; body &gt; conclusion structure.</p><blockquote><p>Your content sucks because you don’t:</p><p>– Hook in the reader</p><p>– Agitate their problem</p><p>– Relate to their problem</p><p>– Give them a valuable solution</p><p>Human psychology will always beat what you think will work.</p><p>Clear, not clever.</p></blockquote><p>I’m writing these on the spot, so these won’t be perfect, but do this along with me.</p><p>Pick one of your main interests, craft a hook, give actionable value, and wrap it up nicely.</p><p>Practice makes perfect.</p><h3 id="importance-of-a-topic" tabindex="-1">Importance Of A Topic <a class="header-anchor" href="#importance-of-a-topic" aria-label="Permalink to &quot;Importance Of A Topic&quot;">​</a></h3><p>Most people don’t care about what you are writing about because they don’t understand its importance.</p><p>So, instead of packing up your bags and blaming the system…</p><p>Teach them why it’s important.</p><p><em>This is how you make your interests interesting to other people.</em></p><p>Make them aware of how it can impact their life.</p><blockquote><p>Marketing is the greatest skill you can learn.</p><p>Why?</p><p>– It pairs with any other skill</p><p>– It teaches you human psychology</p><p>– It helps you monetize a niche interest</p><p>Only a fool expects to make an income without learning the skill that turns scrollers into customers.</p></blockquote><p>Here’s a great example I swiped from Taylin Simmonds on Twitter:</p><p><img src="'+o+'" alt=""></p><p>Try it out.</p><p>Why is your main topic important?</p><p>How has it impacted your life?</p><p>Why should other people care?</p><p>Self-reflect and write a post on it.</p><h3 id="calling-out-common-mistakes-or-problems" tabindex="-1">Calling Out Common Mistakes Or Problems <a class="header-anchor" href="#calling-out-common-mistakes-or-problems" aria-label="Permalink to &quot;Calling Out Common Mistakes Or Problems&quot;">​</a></h3><p>A great way to establish authority in your topic is to call out bad advice, common mistakes, or problems.</p><p>This shows that you have experience and that you want to help your readers.</p><blockquote><p>Stop writing hyper-specific content.</p><p>As a beginner, you should be focused on growth.</p><p>– Make your writing relatable</p><p>– Focus on a common problem</p><p>– Talk about the topic from a high level</p><p>Don’t expect to grow if only a few people would share your content.</p></blockquote><p>This leads into my next advice.</p><h2 id="how-to-get-the-most-out-of-your-writing" tabindex="-1">How To Get The Most Out Of Your Writing <a class="header-anchor" href="#how-to-get-the-most-out-of-your-writing" aria-label="Permalink to &quot;How To Get The Most Out Of Your Writing&quot;">​</a></h2><p>Beginner creators struggle with seeing the big picture of content creation.</p><p>You aren’t aiming for an immediate sale with every post.</p><p>Your posts are not sales pages (but knowing how to write sales pages can help with your posts).</p><p>When you look at your writing, it should be obvious whether or not it would be shared by the average person scrolling on social media.</p><p>If it’s not, and you don’t have a growth strategy in your niche, how do you expect to grow?</p><p>Shares are the engine for organic brand growth.</p><p>Zoom out and realize that your content, over time, will introduce people to what you have to offer.</p><p>When the time comes, and if you have the skill, they will buy from you.</p><h3 id="broaden-your-content" tabindex="-1">Broaden Your Content <a class="header-anchor" href="#broaden-your-content" aria-label="Permalink to &quot;Broaden Your Content&quot;">​</a></h3><p>From the tweets I wrote above, are they authoritative?</p><p>Yes.</p><p>Will they attract a potential customer (assuming I have more value they can find outside of my content)?</p><p>Yes.</p><p>Are they so specific that they won’t get shared?</p><p>No.</p><p>This is the balance you have to strike on top-of-funnel social media.</p><p>Then, when you bring them to your newsletter, lead magnet, and product sales pages – that’s where you get as specific as necessary.</p><p>If your content seems like it wouldn’t be shared by a beginner, zoom out one layer and rewrite it.</p><h3 id="study-the-best-content-structures" tabindex="-1">Study The Best Content Structures <a class="header-anchor" href="#study-the-best-content-structures" aria-label="Permalink to &quot;Study The Best Content Structures&quot;">​</a></h3><p>Before we start writing content other than lists, I would recommend you study what good content looks like.</p><p>I personally use <a href="http://tweethunter.io/?via=thedankoe" target="_blank" rel="noreferrer">TweetHunter</a> (a software) and Twemex (a chrome plugin) to quickly see my favorite accounts’ top content.</p><p>You can also use Twitter’s advanced search to do this by typing in:</p><p><em>from:thedankoe min_faves:1000</em></p><p>To your Twitter search bar.</p><p>Just replace my username with someone else’s and change the minimum likes to anything you’d like.</p><p>Immerse yourself in that content and use it as training wheels for your own.</p><p>What topics do you use to practice with this?</p><h3 id="repurpose-your-list-style-content" tabindex="-1">Repurpose Your List Style Content <a class="header-anchor" href="#repurpose-your-list-style-content" aria-label="Permalink to &quot;Repurpose Your List Style Content&quot;">​</a></h3><p>The lists you wrote above have multiple bullet points that can be turned into it’s own content.</p><p>These lists can also be turned into the outline of a thread, carousel, or newsletter.</p><p>(I would highly recommend doing this to establish authority even more).</p><p>For now, let’s focus on writing another short post.</p><p>From the first tweet we wrote above, the first bullet point is “hook in your reader.”</p><p>And if I take one of my high-performing tweet structures like this one with 9,000 likes:</p><p><img src="'+a+'" alt=""></p><p>Then I can write a new tweet:</p><p>The greatest digital skill is the ability to capture, hold, and deliver value on attention.</p><p>That could be better, but I know that one will do well.</p><p>You can see how simple all of this content writing stuff is if you follow these exact steps with all of your interests.</p><p>To recap:</p><ul><li>You can, and should, incorporate your interests to make your brand authentic</li><li>Create a topic tree that you can master in 6-12 months through writing</li><li>Write multiple list-style content pieces to establish authority in your main interest</li><li>Broaden your writing if you don’t think it will be shared</li><li>Study the best content structures, use them as training wheels, and branch off of what you’ve already written</li></ul><p>This is all you need to get started with content creation.</p><p>In the next letter, we will discuss how you can get that content shared without spending a penny.</p><p>Hope you enjoyed this one, my friends.</p><p>Talk soon.</p><p>– DK</p><p><strong>How I Can Help You When You Are Ready</strong></p><p>Solopreneur Sprints starts on February 7th. We will create your niche of one, write 20+ content pieces together, and craft a growth strategy so you can eventually do this full time.</p><p><a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">Enroll here for $150.</a></p><p>2 Hour Writer teaches you high impact creative writing in a practical setting. I help you build out your content ecosystem and stand out from the sea of other creators.</p><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">Enroll in 2HW here.</a></p><p>Modern Mastery is a private community for all things marketing, sales, personal development, and performance. Get instant access to a strategy library, personalized help in the Discord, and more.</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Readers can join for $5.</a></p>',160)])])}const g=r(p,[["render",h]]);export{f as __pageData,g as default};
